export const KEY='find-yourjob:v1';
export const emptyState=()=>({saved:[],plans:{},posts:[],answers:{},draft:{},name:'Alex',stage:'all'});
export function readState(storage){try{const raw=JSON.parse(storage.getItem(KEY)||'null');if(!raw||typeof raw!=='object'||Array.isArray(raw))return emptyState();const text=(v,max=5000)=>typeof v==='string'?v.slice(0,max):'';const record=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{};const space=v=>['design','research','data'].includes(v)?v:'design';const plans={};for(const id of ['design-task','data-task','interview-task']){if(raw.plans?.[id]&&typeof raw.plans[id]==='object'){const p=raw.plans[id];plans[id]={notes:[0,1,2].map(i=>text(p.notes?.[i])),checks:[0,1,2].map(i=>p.checks?.[i]===true),reflection:text(p.reflection),complete:p.complete===true&&[0,1,2].every(i=>p.checks?.[i]===true)&&text(p.reflection).trim().length>=10};}}const posts=(Array.isArray(raw.posts)?raw.posts:[]).filter(x=>x&&typeof x.id==='string'&&/^local-[a-z0-9-]+$/i.test(x.id)&&typeof x.title==='string'&&typeof x.excerpt==='string').map(x=>({id:x.id,kind:'question',stage:'both',space:space(x.space),title:text(x.title,160),excerpt:text(x.excerpt,4000),author:text(x.author,40)||'Anonymous explorer',initials:text(x.initials,2)||'AE',tags:'Your local question',local:true,replies:[]}));const answers=Object.fromEntries(Object.entries(record(raw.answers)).filter(([id,a])=>!['__proto__','constructor','prototype'].includes(id)&&Array.isArray(a)).map(([id,a])=>[id,a.filter(x=>x&&typeof x.text==='string').map(x=>({name:text(x.name,40)||'Explorer',text:text(x.text,3000),local:true}))]));const d=record(raw.draft);return {...emptyState(),saved:Array.isArray(raw.saved)?[...new Set(raw.saved.filter(x=>typeof x==='string'))]:[],plans,posts,answers,draft:{title:text(d.title,160),body:text(d.body,4000),space:space(d.space),anonymous:d.anonymous===true},name:text(raw.name,40).trim()||'Alex',stage:['all','first','change'].includes(raw.stage)?raw.stage:'all'};}catch{return emptyState();}}
export function saveState(storage,state){try{storage.setItem(KEY,JSON.stringify(state));return true;}catch{return false;}}
export function escapeHTML(value=''){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function filterItems(items,{kind='all',query='',stage='all',space='all'}={}){const terms=query.trim().toLowerCase().split(/\s+/).filter(Boolean);return items.filter(x=>(kind==='all'||x.kind===kind)&&(stage==='all'||x.stage==='both'||x.stage===stage)&&(space==='all'||x.space===space)&&terms.every(t=>`${x.title} ${x.excerpt} ${x.space} ${x.author||''} ${x.tags||''}`.toLowerCase().includes(t)));}
export function toggleSaved(state,id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];return state.saved.includes(id);}
export function ensurePlan(state,id){if(!state.plans[id]||typeof state.plans[id]!=='object')state.plans[id]={notes:['','',''],checks:[false,false,false],reflection:'',complete:false};return state.plans[id];}
export const content=[
{id:'architecture',kind:'story',stage:'change',space:'design',title:'From architecture to product design',excerpt:'What I kept, what I had to unlearn, and why I tried it before making the leap.',author:'Jamie Chen',initials:'JC',image:'architect.png',tags:'8 years in architecture · A new direction',body:[['The starting point','I enjoyed working through complicated problems with people. What I wanted to change was the rhythm of my work, not everything I had learned.'],['A small experiment','Before making any big decisions, I redesigned a confusing booking experience as a practice project. I spoke with three friends about the problem and kept a journal of what I enjoyed.'],['What carried over','Explaining trade-offs, working within constraints, and making ideas visible were familiar. Research methods and digital interaction patterns took deliberate practice.'],['What was harder','Enjoying a project did not mean I was ready for a new job. I needed feedback on my reasoning, not just on how polished the screens looked.'],['A useful next step','Try a small project alongside your current work. Notice the tasks you enjoy and the ones you avoid. Then ask a practitioner to review your process.']]},
{id:'major',kind:'story',stage:'first',space:'research',title:"Your major isn't your only path",excerpt:'A first-career story about following curiosity without throwing away what you already know.',author:'Sofia Patel',initials:'SP',image:'graduate.png',tags:'First career · Exploring possibilities',body:[['A different kind of question','Rather than asking which job title matched my degree, I wrote down the activities I actually enjoyed: listening, finding patterns, and explaining ideas.'],['Trying the work','I made an interview guide for a student project and practiced with a friend. Writing useful, open questions was harder than it looked.'],['A more honest decision','One exercise did not choose my career for me. It gave me a concrete question to ask someone working in research: how much of your week feels like this?'],['What I would do next','Read contrasting experiences, try another task, and ask about the less visible parts of the role before committing to a course.']]},
{id:'design-task',kind:'task',stage:'both',space:'design',title:'Think like a product designer',excerpt:'Turn an everyday frustration into a thoughtful first idea.',tags:'30 min · Beginner friendly',steps:[['Notice a problem','Choose one small frustration in daily life. Who experiences it, and what are they trying to do?'],['Ask a better question','Write three open questions you could ask someone about this problem. Avoid suggesting a solution in the question.'],['Sketch an idea','Describe or sketch one possible improvement. Write down an assumption you would still need to test.']]},
{id:'start-over',kind:'question',stage:'change',space:'design',title:'Can I change careers without starting over?',excerpt:"I have five years of experience in marketing, but I'm drawn to product design. What could I try alongside my current job?",author:'Morgan Lee',initials:'ML',tags:'Career change · Transferable skills',replies:[{name:'Jamie',text:'Start by separating the work you enjoy from the job title. A small design project can help you see where your marketing experience contributes and where you need practice.'}]},
{id:'research-day',kind:'question',stage:'both',space:'research',title:'What does a UX researcher actually do all day?',excerpt:"I'm curious about the less visible parts of the role. How do you split your time between interviews, analysis, and working with a team?",author:'Sam Rivera',initials:'SR',tags:'Day-to-day work',replies:[{name:'Sofia',text:'My practice project included preparing questions, arranging conversations, taking notes, and explaining what I learned. Ask people in different teams: the balance can vary a lot.'}]},
{id:'data-task',kind:'task',stage:'both',space:'data',title:'Find the story in a small dataset',excerpt:'Practice asking questions and explaining a pattern, without writing code.',tags:'20 min · Beginner friendly',steps:[['Read the sample','A fictional café sold 18, 24, 20, 31, and 37 coffees from Monday to Friday. What do you notice?'],['Question the pattern','Write two possible explanations and one extra piece of information you would need. These numbers alone do not prove a cause.'],['Tell the story','Summarize your observation in two sentences for the café owner. Separate what you know from what you are guessing.']]},
{id:'interview-task',kind:'task',stage:'both',space:'research',title:'Listen like a user researcher',excerpt:'Practice listening before jumping to an answer.',tags:'25 min · Beginner friendly',steps:[['Pick a familiar experience','Choose a low-stakes everyday activity, such as planning lunch or commuting. What would you like to understand?'],['Write five questions','Use open questions about a past experience. Avoid asking for private or sensitive information.'],['Reflect on your questions','Which question might lead someone toward your preferred answer? Rewrite it and describe what changed.']]},
{id:'course-question',kind:'question',stage:'first',space:'data',title:'What should I try before paying for a course?',excerpt:'I am exploring data analysis after graduation. I would love a small project to test whether I enjoy the work first.',author:'Taylor Kim',initials:'TK',tags:'First career · Learning',replies:[{name:'Morgan',text:'Try explaining a small public or synthetic dataset in plain language. Focus on the question and your uncertainty before choosing a tool or course.'}]}
];
